from typing import Generic, TypeVar, Optional

T = TypeVar('T')

class Option(Generic[T]):
    pass

class Some(Option[T]):
    def __init__(self, value: T):
        self.value = value

class NoneType(Option[T]):
    pass

def divide(a: float, b: float) -> Option[float]:
    if b == 0:
        return NoneType()
    return Some(a / b)

def main():
    result1 = divide(10, 2)
    result2 = divide(10, 0)

    if isinstance(result1, Some):
        print(f"Result: {result1.value}")
    else:
        print("Error: Division by zero")

    if isinstance(result2, Some):
        print(f"Result: {result2.value}")
    else:
        print("Error: Division by zero")

if __name__ == "__main__":
    main()

