import std/string (split)

export func isBalanced(s: string) -> bool {
  let chars = split(s, "") in
  letrec proc = \xs. \cnt.
    match xs {
      [] => cnt == 0,
      x :: rest => {
        let newCnt = if x == "(" then cnt + 1 else if x == ")" then cnt - 1 else cnt;
        if newCnt < 0 then false else proc(rest)(newCnt)
      }
    } in
  proc(chars)(0)
}

export func main() -> () ! {IO} {
  let tests = ["(())", "(()", "())()", "()(())"];
  let printResult = \s. if isBalanced(s) then print("true") else print("false");
  letrec loop = \xs.
    match xs {
      [] => (),
      x :: rest => { printResult(x); loop(rest) }
    } in
  loop(tests)
}

