def isBalanced(s):
    counter = 0
    for char in s:
        if char == '(':
            counter += 1
        elif char == ')':
            counter -= 1
        if counter < 0:
            return False
    return counter == 0

if __name__ == "__main__":
    test_strings = ["(())", "(()", "())()", "()(())"]
    for s in test_strings:
        print("true" if isBalanced(s) else "false")

