class Leaf:
    def __init__(self, value):
        self.value = value

class Branch:
    def __init__(self, left, value, right):
        self.left = left
        self.value = value
        self.right = right

def treeSum(tree):
    if tree is None:
        return 0
    elif isinstance(tree, Leaf):
        return tree.value
    elif isinstance(tree, Branch):
        return tree.value + treeSum(tree.left) + treeSum(tree.right)
    return 0

tree = Branch(
    Branch(
        Leaf(1),
        3,
        Leaf(4)
    ),
    5,
    Branch(
        None,
        8,
        Leaf(10)
    )
)

print(treeSum(tree))

