import std/io (println)
import std/fs (readFile)
import std/string (split, stringToInt)
import std/list (length)

-- Sum a list of integers
export func sumList(xs: [int]) -> int {
  match xs {
    [] => 0,
    x :: rest => x + sumList(rest)
  }
}

-- Parse a line of space-separated integers
export func parseNumbers(line: string) -> [int] {
  let parts = split(line, " ");
  parseNumbersHelper(parts)
}

-- Helper to convert string list to int list
export func parseNumbersHelper(parts: [string]) -> [int] {
  match parts {
    [] => [],
    s :: rest => {
      match stringToInt(s) {
        Some(n) => n :: parseNumbersHelper(rest),
        None => parseNumbersHelper(rest)
      }
    }
  }
}

export func main() -> () ! {IO, FS, Env} {
  let args = getArgs();
  match args {
    [] => println("Error: no filename provided"),
    filename :: _ => {
      let content = readFile(filename);
      let numbers = parseNumbers(content);
      let result = sumList(numbers);
      println(show(result))
    }
  }
}

