module benchmark/solution

import std/fs (readFile)
import std/json (Json, JObject, JString, JNumber, JArray, JNull, decode)
import std/string (split)
import std/list (length)
import std/result (Result, Ok, Err)

-- Helper: Count dots in a string by splitting
func countDots(s: string) -> int {
  let parts = split(s, ".");
  length(parts) - 1
}

-- Helper: Find a key in a JSON object
func findKey(kvs: [{key: string, value: Json}], target: string) -> Json {
  match kvs {
    [] => JNull,
    kv :: rest => if kv.key == target then kv.value else findKey(rest, target)
  }
}

-- Helper: Count JSON array elements
func countArray(j: Json) -> int {
  match j {
    JArray(items) => countArrayList(items),
    _ => 0
  }
}

func countArrayList(items: [Json]) -> int {
  match items {
    [] => 0,
    _ :: rest => 1 + countArrayList(rest)
  }
}

-- Helper: Extract string from JSON
func getString(j: Json) -> string {
  match j {
    JString(s) => s,
    _ => ""
  }
}

-- Helper: Extract number as int from JSON
func getInt(j: Json) -> int {
  match j {
    JNumber(n) => floatToInt(n),
    _ => 0
  }
}

export func main() -> () ! {IO, FS} {
  -- Read the JSON file
  let json_str = readFile("app_config.json");

  -- Parse JSON
  let parsed = decode(json_str);

  match parsed {
    Ok(JObject(kvs)) => {
      -- Extract fields
      let app_name = getString(findKey(kvs, "app_name"));
      let version = getString(findKey(kvs, "version"));
      let port = getInt(findKey(kvs, "port"));
      let features = findKey(kvs, "features");

      -- Validate port (between 1024 and 65535)
      let port_valid = port >= 1024 && port <= 65535;

      -- Validate version (exactly two dots)
      let dot_count = countDots(version);
      let version_valid = dot_count == 2;

      -- Validate features not empty
      let feature_count = countArray(features);
      let features_valid = feature_count > 0;

      -- Check all validations
      if port_valid && version_valid && features_valid
      then print("Loaded " ++ app_name ++ " v" ++ version ++ " on port " ++ show(port) ++ " with " ++ show(feature_count) ++ " features")
      else print("Validation failed")
    },
    Ok(_) => print("Invalid JSON format"),
    Err(msg) => print("JSON parse error: " ++ msg)
  }
}

module benchmark/solution

import std/fs (readFile, writeFile)
import std/io (print)
import std/string (split, trim, find, stringToInt)
import std/json (encode, jo, kv, js, jnum)
import std/list (map, filter)

pure func parseAge(s: string) -> int {
  match stringToInt(trim(s)) {
    Some(n) => n,
    None => -1
  }
}

pure func validateEmail(email: string) -> bool {
  find(email, "@") >= 0
}

pure func validateRow(fields: [string]) -> bool {
  match fields {
    name :: age :: email :: [] => {
      let ageVal = parseAge(age);
      let emailClean = trim(email);
      ageVal > 0 && validateEmail(emailClean)
    },
    _ => false
  }
}

pure func makeRecord(name: string, age: int, email: string) -> {name: string, age: int, email: string} {
  {name: name, age: age, email: email}
}

pure func parseRow(fields: [string]) -> {name: string, age: int, email: string} {
  match fields {
    name :: age :: email :: [] => makeRecord(trim(name), parseAge(age), trim(email)),
    _ => makeRecord("", 0, "")
  }
}

pure func rowToJson(row: {name: string, age: int, email: string}) -> string {
  encode(jo([
    kv("name", js(row.name)),
    kv("age", jnum(intToFloat(row.age))),
    kv("email", js(row.email))
  ]))
}

pure func processLines(lines: [string]) -> [string] {
  match lines {
    [] => [],
    header :: rows => {
      let fieldsList = map(\line. split(line, ","), rows);
      let validRows = filter(validateRow, fieldsList);
      let parsed = map(parseRow, validRows);
      map(rowToJson, parsed)
    }
  }
}

pure func joinStrings(strs: [string], sep: string) -> string {
  match strs {
    [] => "",
    s :: [] => s,
    s :: rest => s ++ sep ++ joinStrings(rest, sep)
  }
}

pure func buildJsonArray(jsonRows: [string]) -> string {
  match jsonRows {
    [] => "[]",
    _ => "[" ++ joinStrings(jsonRows, ",") ++ "]"
  }
}

pure func countRows(jsonRows: [string]) -> int {
  match jsonRows {
    [] => 0,
    _ :: rest => 1 + countRows(rest)
  }
}

export func main() -> () ! {IO, FS} {
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com";
  writeFile("users.csv", csvContent);

  let content = readFile("users.csv");
  let lines = split(content, "\n");
  let jsonRows = processLines(lines);
  let jsonArray = buildJsonArray(jsonRows);

  writeFile("users.json", jsonArray);

  let count = countRows(jsonRows);
  print("Converted " ++ show(count) ++ " valid rows to users.json")
}

