import csv
import json


def validate_row(row):
    """Validate a CSV row according to requirements."""
    try:
        # Check age is a positive integer
        age = int(row['age'])
        if age <= 0:
            return False

        # Check email contains "@"
        if '@' not in row['email']:
            return False

        return True
    except (ValueError, KeyError):
        return False


def main():
    valid_rows = []

    # Read and parse CSV file
    with open('users.csv', 'r') as csv_file:
        reader = csv.DictReader(csv_file)

        for row in reader:
            if validate_row(row):
                # Convert age to integer for JSON output
                valid_rows.append({
                    'name': row['name'],
                    'age': int(row['age']),
                    'email': row['email']
                })

    # Write to JSON file
    with open('users.json', 'w') as json_file:
        json.dump(valid_rows, json_file)

    # Print result
    print(f"Converted {len(valid_rows)} valid rows to users.json")


if __name__ == "__main__":
    main()

