from typing import TypeVar, Generic

# Type markers for effects
T = TypeVar('T')

class Pure(Generic[T]):
    """Marker type for pure functions"""
    def __init__(self, value: T):
        self.value = value

    def run(self) -> T:
        return self.value

class Effect(Generic[T]):
    """Marker type for effectful functions"""
    def __init__(self, value: T):
        self.value = value

    def run(self) -> T:
        return self.value

# PURE functions
def double(x: int) -> Pure[int]:
    """Pure function: doubles the input"""
    return Pure(x * 2)

def add(a: int, b: int) -> Pure[int]:
    """Pure function: adds two numbers"""
    return Pure(a + b)

# EFFECTFUL functions
def printResult(label: str, value: int) -> Effect[None]:
    """Effectful function: prints to stdout"""
    print(f"{label}: {value}")
    return Effect(None)

def compute_and_print() -> Effect[None]:
    """Effectful function: combines pure computations with effects"""
    # Call pure functions and extract values
    result1 = double(5).run()
    result2 = add(result1, 3).run()
    # Call effectful function
    printResult("Result", result2)
    return Effect(None)

if __name__ == "__main__":
    compute_and_print()

