from typing import Union, Generic, TypeVar

T = TypeVar('T')

class Result(Generic[T]):
    def __init__(self, value: Union[T, str], is_ok: bool):
        self._value = value
        self._is_ok = is_ok

    def is_ok(self) -> bool:
        return self._is_ok

    def is_err(self) -> bool:
        return not self._is_ok

    def unwrap(self) -> T:
        if self._is_ok:
            return self._value
        raise ValueError(f"Called unwrap on an Err value: {self._value}")

    def unwrap_err(self) -> str:
        if not self._is_ok:
            return self._value
        raise ValueError(f"Called unwrap_err on an Ok value: {self._value}")

def Ok(value: T) -> Result[T]:
    return Result(value, True)

def Err(message: str) -> Result:
    return Result(message, False)

def parse_int(s: str) -> Result[int]:
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def main():
    # Test case 1: parse_int("10") then divide by 2 -> "Result: 5"
    result1 = parse_int("10")
    if result1.is_ok():
        result1 = divide_safe(result1.unwrap(), 2)
    if result1.is_ok():
        print(f"Result: {result1.unwrap()}")
    else:
        print(f"Error: {result1.unwrap_err()}")

    # Test case 2: parse_int("10") then divide by 0 -> "Error: Division by zero"
    result2 = parse_int("10")
    if result2.is_ok():
        result2 = divide_safe(result2.unwrap(), 0)
    if result2.is_ok():
        print(f"Result: {result2.unwrap()}")
    else:
        print(f"Error: {result2.unwrap_err()}")

    # Test case 3: parse_int("abc") -> "Error: Invalid integer"
    result3 = parse_int("abc")
    if result3.is_ok():
        result3 = divide_safe(result3.unwrap(), 2)
    if result3.is_ok():
        print(f"Result: {result3.unwrap()}")
    else:
        print(f"Error: {result3.unwrap_err()}")

if __name__ == "__main__":
    main()

