from dataclasses import dataclass

@dataclass
class Num:
    value: int

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

Expr = Num | Add | Mul

def eval(expr: Expr) -> int:
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Add):
        return eval(expr.left) + eval(expr.right)
    elif isinstance(expr, Mul):
        return eval(expr.left) * eval(expr.right)

# Construct the expression: (3 + 4) * (2 + 5)
expression = Mul(Add(Num(3), Num(4)), Add(Num(2), Num(5)))

# Evaluate and print the result
result = eval(expression)
print(result)

