-- Helper: Check if node is in visited list
export func contains(node: int, visited: [int]) -> bool {
  match visited {
    [] => false,
    x :: rest => if x == node then true else contains(node, rest)
  }
}

-- Helper: Get neighbors for a node from adjacency list
export func getNeighbors(node: int, graph: []) -> [int] {
  match graph {
    [] => [],
    entry :: rest => {
      let n = entry.0;
      let neighbors = entry.1;
      if n == node then neighbors else getNeighbors(node, rest)
    }
  }
}

-- BFS implementation
export func bfs(queue: [int], visited: [int], graph: []) -> [int] {
  match queue {
    [] => visited,
    node :: rest => {
      if contains(node, visited)
      then bfs(rest, visited, graph)
      else {
        let neighbors = getNeighbors(node, graph);
        let newVisited = concat(visited, [node]);
        let newQueue = concat(rest, neighbors);
        bfs(newQueue, newVisited, graph)
      }
    }
  }
}

