def contains(x, lst):
    for item in lst:
        if item == x:
            return True
    return False


def enqueue(x, queue):
    queue.append(x)


def bfs(graph, start):
    visited = []
    queue = []

    # Add starting node to queue
    enqueue(start, queue)

    while len(queue) > 0:
        # Remove from front of queue
        current = queue[0]
        queue = queue[1:]

        # Skip if already visited
        if contains(current, visited):
            continue

        # Mark as visited
        visited.append(current)

        # Find neighbors in graph
        for node, neighbors in graph:
            if node == current:
                # Add neighbors to queue
                for neighbor in neighbors:
                    if not contains(neighbor, visited):
                        enqueue(neighbor, queue)
                break

    return visited


def main():
    # Graph representation as adjacency list
    graph = [(1, [2, 3]), (2, [4]), (3, [4, 5]), (4, []), (5, [])]

    # Run BFS starting from node 1
    result = bfs(graph, 1)

    # Print visited nodes in order
    for node in result:
        print(node)


if __name__ == "__main__":
    main()

