type Term =
  | TVar(string)
  | TLam(string, Term)
  | TApp(Term, Term)

func showTerm(term: Term) -> string {
  match term {
    TVar(name) => name,
    TLam(param, body) => "(λ" ++ param ++ "." ++ showTerm(body) ++ ")",
    TApp(f, arg) => "(" ++ showTerm(f) ++ " " ++ showTerm(arg) ++ ")"
  }
}

func subst(term: Term, var_name: string, replacement: Term) -> Term {
  match term {
    TVar(name) =>
      if compare(name, var_name) == 0 then replacement else term,
    TLam(param, body) =>
      if compare(param, var_name) == 0
      then term
      else TLam(param, subst(body, var_name, replacement)),
    TApp(f, arg) =>
      TApp(subst(f, var_name, replacement), subst(arg, var_name, replacement))
  }
}

func eval(term: Term) -> Term {
  match term {
    TVar(_) => term,
    TLam(_, _) => term,
    TApp(f, arg) => {
      let f_val = eval(f);
      let arg_val = eval(arg);
      match f_val {
        TLam(param, body) => {
          let new_body = subst(body, param, arg_val);
          eval(new_body)
        },
        _ => TApp(f_val, arg_val)
      }
    }
  }
}

