from dataclasses import dataclass
from typing import Union


@dataclass
class TVar:
    """Variable term"""
    name: str

    def __repr__(self):
        return self.name


@dataclass
class TLam:
    """Lambda abstraction: λx.body"""
    param: str
    body: "Term"

    def __repr__(self):
        return f"λ{self.param}.{self.body}"


@dataclass
class TApp:
    """Application: f x"""
    func: "Term"
    arg: "Term"

    def __repr__(self):
        return f"({self.func} {self.arg})"


Term = Union[TVar, TLam, TApp]


def subst(term: Term, var: str, replacement: Term) -> Term:
    """Substitute var with replacement in term"""
    if isinstance(term, TVar):
        if term.name == var:
            return replacement
        else:
            return term
    elif isinstance(term, TLam):
        if term.param == var:
            # Variable shadowing - don't substitute inside lambda with same parameter
            return term
        else:
            # Substitute in the body
            return TLam(term.param, subst(term.body, var, replacement))
    elif isinstance(term, TApp):
        # Substitute in both function and argument
        return TApp(subst(term.func, var, replacement), subst(term.arg, var, replacement))
    else:
        raise ValueError(f"Unknown term type: {type(term)}")


def eval_term(term: Term) -> Term:
    """Evaluate term using call-by-value"""
    if isinstance(term, TVar):
        # Variables evaluate to themselves
        return term
    elif isinstance(term, TLam):
        # Lambdas are values
        return term
    elif isinstance(term, TApp):
        # Evaluate function and argument
        func = eval_term(term.func)
        arg = eval_term(term.arg)

        # If function is a lambda, apply it
        if isinstance(func, TLam):
            # Substitute the parameter with the argument in the body
            body_substituted = subst(func.body, func.param, arg)
            # Recursively evaluate the result
            return eval_term(body_substituted)
        else:
            # If not a lambda, return the application as is
            return TApp(func, arg)
    else:
        raise ValueError(f"Unknown term type: {type(term)}")


def main():
    # Evaluate: (λx. λy. x) 1 2
    # This is the K combinator applied to 1 and 2
    # Expected result: TVar("1")

    term = TApp(
        TApp(
            TLam("x", TLam("y", TVar("x"))),
            TVar("1")
        ),
        TVar("2")
    )

    result = eval_term(term)
    print(result)


if __name__ == "__main__":
    main()

