-- Count occurrences of a value in a list
export func countOccurrences[a](xs: [a], target: a, eq: (a, a) -> bool) -> int {
  match xs {
    [] => 0,
    x :: rest =>
      let count = countOccurrences(rest, target, eq) in
      if eq(x, target) then 1 + count else count
  }
}

-- Check string equality
export func stringEq(a: string, b: string) -> bool {
  a == b
}

-- Extract level from a log line
export func extractLevel(line: string) -> string {
  let parts = split(line, " ");
  match parts {
    [] => "",
    _ :: [] => "",
    _ :: _ :: [] => "",
    _ :: _ :: level :: _ => level
  }
}

-- Extract username from message (after colon)
export func extractUser(message: string) -> string {
  match split(message, ": ") {
    [] => "",
    [_] => "",
    _ :: rest => {
      match rest {
        [] => "",
        user :: _ => {
          let words = split(user, " ");
          match words {
            [] => "",
            w :: _ => w
          }
        }
      }
    }
  }
}

-- Check if a user is in the list
export func userInList(users: [string], user: string) -> bool {
  match users {
    [] => false,
    u :: rest =>
      if u == user then true else userInList(rest, user)
  }
}

-- Add user if not already in list
export func addUserIfNew(users: [string], user: string) -> [string] {
  if user == "" then users
  else if userInList(users, user) then users
  else users ++ [user]
}

-- Collect unique users from log lines
export func collectUsers(lines: [string], acc: [string]) -> [string] {
  match lines {
    [] => acc,
    line :: rest => {
      let parts = split(line, " ");
      let message = match parts {
        a :: b :: c :: d :: e :: f :: g =>
          let tail = split(line, " ") in
          match tail {
            _ :: _ :: _ :: msg_parts => {
              match msg_parts {
                m :: rest2 => m,
                _ => ""
              }
            },
            _ => ""
          },
        _ => ""
      };
      let user = extractUser(message);
      let newAcc = addUserIfNew(acc, user);
      collectUsers(rest, newAcc)
    }
  }
}

-- Simple bubble sort for strings
export func sortStrings(xs: [string]) -> [string] {
  match xs {
    [] => [],
    [x] => [x],
    x :: rest => {
      let sorted_rest = sortStrings(rest);
      insertSorted(x, sorted_rest)
    }
  }
}

-- Insert a string in sorted position
export func insertSorted(x: string, xs: [string]) -> [string] {
  match xs {
    [] => [x],
    y :: rest =>
      if x <= y then x :: y :: rest
      else y :: insertSorted(x, rest)
  }
}

-- Join strings with separator
export func joinWith(sep: string, xs: [string]) -> string {
  match xs {
    [] => "",
    [x] => x,
    x :: rest => x ++ sep ++ joinWith(sep, rest)
  }
}

-- Extract user from message
export func extractUserFromMessage(msg: string) -> string {
  let parts = split(msg, ": ");
  match parts {
    [] => "",
    [_] => "",
    _ :: user_part :: _ => {
      let userWithRest = user_part;
      let userWords = split(userWithRest, " ");
      match userWords {
        [] => "",
        u :: _ => u
      }
    }
  }
}

-- Collect unique users - revised
export func getUniqueUsers(lines: [string]) -> [string] {
  let allUsers = match lines {
    [] => [],
    _ => collectUsersHelper(lines, [])
  };
  sortStrings(allUsers)
}

-- Helper to collect users
export func collectUsersHelper(lines: [string], acc: [string]) -> [string] {
  match lines {
    [] => acc,
    line :: rest => {
      let parts = split(line, " ");
      let level = match parts {
        _ :: _ :: l :: _ => l,
        _ => ""
      };
      let user = if level == "INFO" then extractUserFromMessage(line) else "";
      let newAcc = if user == "" then acc else addUserIfNew(acc, user);
      collectUsersHelper(rest, newAcc)
    }
  }
}

export func main() -> () ! {IO, FS} {
  -- Create the log file
  let logContent = "2024-10-29 10:00:00 INFO User logged in: alice\n2024-10-29 10:01:15 ERROR Database connection failed\n2024-10-29 10:02:30 INFO User logged in: bob\n2024-10-29 10:03:45 WARNING High memory usage: 85%\n2024-10-29 10:05:00 ERROR API timeout: /users endpoint\n2024-10-29 10:06:15 INFO User logged out: alice";
  writeFile("app.log", logContent);

  -- Read and parse the log file
  let content = readFile("app.log");
  let lines = split(content, "\n");
  let totalCount = length(lines);

  -- Count each level
  let infoCount = countOccurrences(lines, "INFO", \l. \r. extractLevel(l) == r);
  let errorCount = countOccurrences(lines, "ERROR", \l. \r. extractLevel(l) == r);
  let warningCount = countOccurrences(lines, "WARNING", \l. \r. extractLevel(l) == r);

  -- Calculate percentages
  let infoPct = if totalCount > 0 then (infoCount * 100) / totalCount else 0;
  let errorPct = if totalCount > 0 then (errorCount * 100) / totalCount else 0;
  let warningPct = if totalCount > 0 then (warningCount * 100) / totalCount else 0;

  -- Get unique users
  let users = getUniqueUsers(lines);
  let usersStr = joinWith(", ", users);

  -- Print results
  println("Total log entries: " ++ show(totalCount));
  println("INFO: " ++ show(infoCount) ++ " (" ++ show(infoPct) ++ "%)");
  println("ERROR: " ++ show(errorCount) ++ " (" ++ show(errorPct) ++ "%)");
  println("WARNING: " ++ show(warningCount) ++ " (" ++ show(warningPct) ++ "%)");
  println("Unique users: " ++ usersStr)
