func take[a](n: int, xs: [a]) -> [a] {
  if n <= 0 then []
  else match xs {
    [] => [],
    x :: rest => x :: take(n - 1, rest)
  }
}

func drop[a](n: int, xs: [a]) -> [a] {
  if n <= 0 then xs
  else match xs {
    [] => [],
    _ :: rest => drop(n - 1, rest)
  }
}

export func merge(xs: [int], ys: [int]) -> [int] {
  match (xs, ys) {
    ([], ys) => ys,
    (xs, []) => xs,
    (x :: restx, y :: resty) =>
      if x <= y
      then x :: merge(restx, ys)
      else y :: merge(xs, resty)
  }
}

export func split(xs: [int]) -> ([int], [int]) {
  let mid = length(xs) / 2;
  (take(mid, xs), drop(mid, xs))
}

export func mergeSort(xs: [int]) -> [int] {
  match xs {
    [] => [],
    [_] => xs,
    _ => {
      match split(xs) {
        (left, right) => {
          let sortedLeft = mergeSort(left);
          let sortedRight = mergeSort(right);
          merge(sortedLeft, sortedRight)
        }
      }
    }
  }
}

