from typing import Optional, TypeVar, Callable, List

T = TypeVar('T')
U = TypeVar('U')

class Option:
    """Base class for Option type"""
    pass

class Some(Option):
    def __init__(self, value: T):
        self.value = value

class Nothing(Option):
    pass

# Singleton instance of Nothing
None_ = Nothing()

def findFirst(predicate: Callable[[T], bool], lst: List[T]) -> Option:
    """Find first element matching predicate, return Some(element) or None"""
    for element in lst:
        if predicate(element):
            return Some(element)
    return None_

def mapOption(fn: Callable[[T], U], option: Option) -> Option:
    """Apply function to value if Some, otherwise return None"""
    if isinstance(option, Some):
        return Some(fn(option.value))
    return None_

