module benchmark/solution

-- 1. Define Color = Red | Black
type Color = Red | Black

-- 2. Define RBTree = Empty | Node(Color, RBTree, int, RBTree)
type RBTree = Empty | Node(Color, RBTree, int, RBTree)

-- 3. Implement balance(color, left, value, right)
-- This function takes the components of a potentially unbalanced node
-- (color, left child, value, right child) and returns a balanced node.
-- It specifically handles the four red-red violation cases by performing
-- rotations and recoloring to produce a structure of the form:
-- Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d))
export func balance(c: Color, l: RBTree, v: int, r: RBTree) -> RBTree {
  match (c, l, v, r) {
    -- Case 1: Black parent, red left child, red left-left grandchild (LL case)
    -- Node(Black, Node(Red, Node(Red, a, x, b), y, c_prime), z, d)
    (Black, Node(Red, Node(Red, a, x, b), y, c_prime), z, d) =>
      Node(Red, Node(Black, a, x, b), y, Node(Black, c_prime, z, d)),

    -- Case 2: Black parent, red left child, red left-right grandchild (LR case)
    -- Node(Black, Node(Red, a, x, Node(Red, b, y, c_prime)), z, d)
    (Black, Node(Red, a, x, Node(Red, b, y, c_prime)), z, d) =>
      Node(Red, Node(Black, a, x, b), y, Node(Black, c_prime, z, d)),

    -- Case 3: Black parent, red right child, red right-left grandchild (RL case)
    -- Node(Black, a, x, Node(Red, Node(Red, b, y, c_prime), z, d))
    (Black, a, x, Node(Red, Node(Red, b, y, c_prime), z, d)) =>
      Node(Red, Node(Black, a, x, b), y, Node(Black, c_prime, z, d)),

    -- Case 4: Black parent, red right child, red right-right grandchild (RR case)
    -- Node(Black, a, x, Node(Red, b, y, Node(Red, c_prime, z, d)))
    (Black, a, x, Node(Red, b, y, Node(Red, c_prime, z, d))) =>
      Node(Red, Node(Black, a, x, b), y, Node(Black, c_prime, z, d)),

    -- Default case: If none of the above patterns match,
    -- it means there is no red-red violation requiring a rotation at this node,
    -- or the current node is Red (which is fine temporarily during insertion,
    -- its Black parent will handle the balancing).
    -- So, simply reconstruct the node as it was.
    _ => Node(c, l, v, r)
  }
}

-- Recursive helper function for insertion.
-- It inserts a new node (always Red) and then calls 'balance' on the way up
-- to fix any red-red violations. It does NOT ensure the root is black.
export func insert_inner(x: int, tree: RBTree) -> RBTree {
  match tree {
    Empty => Node(Red, Empty, x, Empty), -- New nodes are always Red

    Node(c, l, v, r) =>
      if x < v -- Insert into the left subtree
      then balance(c, insert_inner(x, l), v, r)
      else if x > v -- Insert into the right subtree
      then balance(c, l, v, insert_inner(x, r))
      else Node(c, l, v, r) -- Value already exists, do nothing (no duplicates)
  }
}

-- 4. Implement insert(x, tree) that inserts and recolors root to black
-- This function is the public interface for insertion.
-- It calls `insert_inner` and then ensures the resulting root node is Black.
export func insert(x: int, tree: RBTree) -> RBTree {
  match insert_inner(x, tree) {
    -- If the root returned by insert_inner is Red, recolor it to Black.
    Node(Red, l, v, r) => Node(Black, l, v, r),
    -- Otherwise, return the tree as is (it's already Black or Empty).
    t => t
  }
}

-- 5. Implement inorder(tree) to get sorted values
-- Performs an in-order traversal of the tree and collects the values into a sorted list.
export func inorder(tree: RBTree) -> [int] {
  match tree {
    Empty => [],
    Node(_, l, v, r) => inorder(l) ++ [v] ++ inorder(r)
  }
}

-- Helper function to insert a list of values into the tree.
export func insert_all(values: [int], tree: RBTree) -> RBTree {
  match values {
    [] => tree,
    x :: rest => insert_all(rest, insert(x, tree))
  }
}

export func main() -> () ! {IO} {
  -- 6. Insert these values: [7, 3, 18, 10, 22, 8, 11, 26]
  let values_to_insert = [7, 3, 18, 10, 22, 8, 11, 26];

  -- Start with an empty tree.
  let initial_tree = Empty;

  -- Insert all values sequentially.
  let final_tree = insert_all(values_to_insert, initial_tree);

  -- 7. Print the inorder traversal (should be sorted)
  let sorted_values = inorder(final_tree);
  print(show(sorted_values))
}

