from dataclasses import dataclass
from typing import Union

# Define State Type (3 variants)
@dataclass
class Green:
    timer: int

@dataclass
class Yellow:
    timer: int

@dataclass
class Red:
    timer: int

State = Union[Green, Yellow, Red]

# Define Event Type (2 variants)
@dataclass
class Tick:
    pass

@dataclass
class Reset:
    pass

Event = Union[Tick, Reset]

# Transition function with exhaustive pattern matching
def transition(state: State, event: Event) -> State:
    if isinstance(event, Reset):
        # Any state + Reset -> Green with timer=20
        return Green(20)
    elif isinstance(event, Tick):
        if isinstance(state, Green):
            # Green + Tick
            if state.timer > 1:
                return Green(state.timer - 1)
            else:
                return Yellow(3)
        elif isinstance(state, Yellow):
            # Yellow + Tick
            if state.timer > 1:
                return Yellow(state.timer - 1)
            else:
                return Red(10)
        elif isinstance(state, Red):
            # Red + Tick
            if state.timer > 1:
                return Red(state.timer - 1)
            else:
                return Green(20)
        else:
            raise ValueError(f"Unknown state: {state}")
    else:
        raise ValueError(f"Unknown event: {event}")

# Display function
def display(state: State) -> str:
    if isinstance(state, Green):
        return f"GREEN ({state.timer}sec)"
    elif isinstance(state, Yellow):
        return f"YELLOW ({state.timer}sec)"
    elif isinstance(state, Red):
        return f"RED ({state.timer}sec)"
    else:
        raise ValueError(f"Unknown state: {state}")

