module benchmark/solution

type Expr =
  | Const(int)
  | Var(string)
  | Add(Expr, Expr)
  | Mul(Expr, Expr)

export func diff(e: Expr, v: string) -> Expr {
  match e {
    Const(_) => Const(0),
    Var(name) =>
      if name == v
      then Const(1)
      else Const(0),
    Add(e1, e2) =>
      Add(diff(e1, v), diff(e2, v)),
    Mul(e1, e2) =>
      Add(
        Mul(e1, diff(e2, v)),
        Mul(e2, diff(e1, v))
      )
  }
}

export func simplify(e: Expr) -> Expr {
  match e {
    Add(e1, e2) =>
      let s1 = simplify(e1) in
      let s2 = simplify(e2) in
      match (s1, s2) {
        (Const(0), x) => x,
        (x, Const(0)) => x,
        (x, y) => Add(x, y)
      },
    Mul(e1, e2) =>
      let s1 = simplify(e1) in
      let s2 = simplify(e2) in
      match (s1, s2) {
        (Const(0), _) => Const(0),
        (_, Const(0)) => Const(0),
        (Const(1), x) => x,
        (x, Const(1)) => x,
        (x, y) => Mul(x, y)
      },
    Const(n) => Const(n),
    Var(name) => Var(name)
  }
}

export func exprToString(e: Expr) -> string {
  match e {
    Const(n) => "Const(" ++ show(n) ++ ")",
    Var(name) => "Var(" ++ name ++ ")",
    Add(e1, e2) =>
      "Add(" ++ exprToString(e1) ++ ", " ++ exprToString(e2) ++ ")",
