from abc import ABC, abstractmethod

class Expr(ABC):
    @abstractmethod
    def __repr__(self):
        pass

class Const(Expr):
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return f"Const({self.value})"

class Var(Expr):
    def __init__(self, name):
        self.name = name

    def __repr__(self):
        return f"Var({self.name})"

class Add(Expr):
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def __repr__(self):
        return f"Add({self.left}, {self.right})"

class Mul(Expr):
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def __repr__(self):
        return f"Mul({self.left}, {self.right})"

def diff(expr, var):
    """Differentiate an expression with respect to a variable."""
    if isinstance(expr, Const):
        return Const(0)
    elif isinstance(expr, Var):
        if expr.name == var:
            return Const(1)
        else:
            return Const(0)
    elif isinstance(expr, Add):
        left_diff = diff(expr.left, var)
        right_diff = diff(expr.right, var)
        return Add(left_diff, right_diff)
    elif isinstance(expr, Mul):
        # Product rule: d/dx(f * g) = f * dg/dx + g * df/dx
        left = expr.left
        right = expr.right
        left_diff = diff(left, var)
        right_diff = diff(right, var)
        return Add(Mul(left, right_diff), Mul(right, left_diff))
    else:
        raise ValueError(f"Unknown expression type: {type(expr)}")

def simplify(expr):
    """Simplify an expression."""
    if isinstance(expr, Const):
        return expr
    elif isinstance(expr, Var):
        return expr
    elif isinstance(expr, Add):
        left = simplify(expr.left)
        right = simplify(expr.right)

        # 0 + e = e
        if isinstance(left, Const) and left.value == 0:
            return right
        # e + 0 = e
        if isinstance(right, Const) and right.value == 0:
            return left

        # Try to combine like terms
        # Check if left is Var and right is Var (e.g., x + x = 2*x)
        if isinstance(left, Var) and isinstance(right, Var) and left.name == right.name:
            return Mul(Const(2), left)

        # Combine like terms: if both are Mul(c1, v) and Mul(c2, v), combine to Mul(c1+c2, v)
        if isinstance(left, Mul) and isinstance(right, Mul):
            # Check if both have same variable factor
            left_const = None
            left_var = None
            right_const = None
            right_var = None

            if isinstance(left.left, Const) and isinstance(left.right, Var):
                left_const = left.left.value
                left_var = left.right.name
            elif isinstance(left.left, Var) and isinstance(left.right, Const):
                left_const = left.right.value
                left_var = left.left.name

            if isinstance(right.left, Const) and isinstance(right.right, Var):
                right_const = right.left.value
                right_var = right.right.name
            elif isinstance(right.left, Var) and isinstance(right.right, Const):
                right_const = right.right.value
                right_var = right.left.name

            if left_const is not None and right_const is not None and left_var == right_var:
                combined_const = left_const + right_const
                return Mul(Const(combined_const), Var(left_var))

        return Add(left, right)
    elif isinstance(expr, Mul):
        left = simplify(expr.left)
        right = simplify(expr.right)

        # 0 * e = 0
        if isinstance(left, Const) and left.value == 0:
            return Const(0)
        # e * 0 = 0
        if isinstance(right, Const) and right.value == 0:
            return Const(0)
        # 1 * e = e
        if isinstance(left, Const) and left.value == 1:
            return right
        # e * 1 = e
        if isinstance(right, Const) and right.value == 1:
            return left

        return Mul(left, right)
    else:
        return expr

def expr_to_string(expr):
    """Convert expression to infix notation string."""
    if isinstance(expr, Const):
        return str(expr.value)
    elif isinstance(expr, Var):
        return expr.name
    elif isinstance(expr, Add):
        left_str = expr_to_string(expr.left)
        right_str = expr_to_string(expr.right)
        return f"{left_str} + {right_str}"
    elif isinstance(expr, Mul):
        # Special case: constant * variable (e.g., 2x instead of 2 * x)
        if isinstance(expr.left, Const) and isinstance(expr.right, Var):
            if expr.left.value == 1:
                return expr.right.name
            else:
                return f"{expr.left.value}{expr.right.name}"
        elif isinstance(expr.left, Var) and isinstance(expr.right, Const):
            if expr.right.value == 1:
                return expr.left.name
            else:
                return f"{expr.right.value}{expr.left.name}"
        else:
            left_str = expr_to_string(expr.left)
            right_str = expr_to_string(expr.right)
            return f"{left_str} * {right_str}"
    else:
        return str(expr)

# Main: differentiate x^2 + 3x + 5
# Represented as: Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))
expr = Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))

# Differentiate with respect to x
derivative = diff(expr, "x")

# Simplify the derivative
simplified = simplify(derivative)

# Print the result
print(expr_to_string(simplified))

