type Tree =
  | Leaf(int)
  | Node(Tree, int, Tree)

export func concat[a](xs: [a], ys: [a]) -> [a] {
  match xs {
    [] => ys,
    h :: t => h :: concat(t, ys)
  }
}

export func filter[a](pred: a -> bool, xs: [a]) -> [a] {
  match xs {
    [] => [],
    h :: t =>
      if pred(h)
      then h :: filter(pred, t)
      else filter(pred, t)
  }
}

export func join(sep: string, xs: [int]) -> string {
  match xs {
    [] => "",
    [x] => show(x),
    x :: rest => show(x) ++ sep ++ join(sep, rest)
  }
}

export func showList(xs: [int]) -> string {
  "[" ++ join(", ", xs) ++ "]"
}

export func mapTree(fn: int -> int, tree: Tree) -> Tree {
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(left, v, right) =>
      Node(mapTree(fn, left), fn(v), mapTree(fn, right))
  }
}

export func foldTree(fn: int -> int -> int, acc: int, tree: Tree) -> int {
  match tree {
    Leaf(v) => fn(acc)(v),
    Node(left, v, right) => {
      let accLeft = foldTree(fn, acc, left);
      let accV = fn(accLeft)(v);
      foldTree(fn, accV, right)
    }
  }
}

export func treeToList(tree: Tree) -> [int] {
  match tree {
    Leaf(v) => [v],
    Node(left, v, right) =>
      concat(treeToList(left), v :: treeToList(right))
  }
}

export func treeDepth(tree: Tree) -> int {
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => {
      let leftDepth = treeDepth(left);
      let rightDepth = treeDepth(right);
      1 + (if leftDepth > rightDepth then leftDepth else rightDepth)
    }
  }
}

export func main() -> () ! {IO} {
  let tree = Node(
    Node(Leaf(1), 3, Leaf(0)),
    5,
    Node(Leaf(7), 8, Leaf(9))
  );

  let isNotZero = \x. x != 0;

  let original = filter(isNotZero, treeToList(tree));
  print("Original: " ++ showList(original));

  let doubledTree = mapTree(\x. x * 2, tree);
  let doubledList = filter(isNotZero, treeToList(doubledTree));
  print("Doubled: " ++ showList(doubledList));

  let sum = foldTree(\a. \b. a + b, 0, tree);
  print("Sum: " ++ show(sum));

  let depth = treeDepth(tree);
  print("Depth: " ++ show(depth));

  ()
}

