from dataclasses import dataclass
from typing import Union, List, Callable

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]

def map_tree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """Recursively apply function to all values in the tree."""
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:
        return Node(
            map_tree(fn, tree.left),
            fn(tree.value),
            map_tree(fn, tree.right)
        )

def fold_tree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """In-order fold over tree values."""
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:
        # Process left subtree
        acc = fold_tree(fn, acc, tree.left)
        # Process current node
        acc = fn(acc, tree.value)
        # Process right subtree
        return fold_tree(fn, acc, tree.right)

def tree_to_list(tree: Tree) -> List[int]:
    """Convert tree to list using in-order traversal."""
    if isinstance(tree, Leaf):
        # Only include non-zero values (0 is used as dummy)
        return [tree.value] if tree.value != 0 else []
    else:
        left_list = tree_to_list(tree.left)
        right_list = tree_to_list(tree.right)
        return left_list + [tree.value] + right_list

def tree_depth(tree: Tree) -> int:
    """Calculate the depth of the tree."""
    if isinstance(tree, Leaf):
        return 1
    else:
        left_depth = tree_depth(tree.left)
        right_depth = tree_depth(tree.right)
        return 1 + max(left_depth, right_depth)

def main():
    # Build the example tree
    #         5
    #        / \
    #       3   8
    #      /   / \
    #     1   7   9
    tree = Node(
        Node(Leaf(1), 3, Leaf(0)),  # left subtree: 3 with left child 1, dummy right child 0
        5,                           # root value
        Node(Leaf(7), 8, Leaf(9))   # right subtree: 8 with children 7 and 9
    )

    # Original: print in-order values (excluding zeros)
    original = [x for x in tree_to_list(tree) if x != 0]
    print(f"Original: {original}")

    # Doubled: map with lambda x: x * 2
    doubled_tree = map_tree(lambda x: x * 2, tree)
    doubled = [x for x in tree_to_list(doubled_tree) if x != 0]
    print(f"Doubled: {doubled}")

    # Sum: fold with addition starting from 0
    total = fold_tree(lambda a, b: a + b, 0, tree)
    print(f"Sum: {total}")

    # Depth: calculate tree depth
    depth = tree_depth(tree)
    print(f"Depth: {depth}")

if __name__ == "__main__":
    main()

