class Type:
    pass

class TVar(Type):
    def __init__(self, name):
        self.name = name

    def __eq__(self, other):
        return isinstance(other, TVar) and self.name == other.name

class TInt(Type):
    def __eq__(self, other):
        return isinstance(other, TInt)

class TBool(Type):
    def __eq__(self, other):
        return isinstance(other, TBool)

class TFunc(Type):
    def __init__(self, arg_type, result_type):
        self.arg_type = arg_type
        self.result_type = result_type

    def __eq__(self, other):
        return isinstance(other, TFunc) and self.arg_type == other.arg_type and self.result_type == other.result_type

def apply(subst, type_):
    if isinstance(type_, TVar):
        for var_name, var_type in subst:
            if var_name == type_.name:
                return apply(subst, var_type)
        return type_
    elif isinstance(type_, TFunc):
        return TFunc(apply(subst, type_.arg_type), apply(subst, type_.result_type))
    else:
        return type_

def compose(subst1, subst2):
    result = []
    for var, t in subst2:
        result.append((var, apply(subst1, t)))
    for var, t in subst1:
        if not any(v == var for v, _ in subst2):
            result.append((var, t))
    return result

def unify(t1, t2):
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    elif isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    elif isinstance(t1, TVar):
        return [(t1.name, t2)]
    elif isinstance(t2, TVar):
        return [(t2.name, t1)]
    elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
        subst1 = unify(t1.arg_type, t2.arg_type)
        if subst1 is None:
            return None
        arg2_subst = apply(subst1, t2.result_type)
        arg1_subst = apply(subst1, t1.result_type)
        subst2 = unify(arg1_subst, arg2_subst)
        if subst2 is None:
            return None
        return compose(subst2, subst1)
    else:
        return None

def type_to_string(t):
    if isinstance(t, TInt):
        return "TInt"
    elif isinstance(t, TBool):
        return "TBool"
    elif isinstance(t, TVar):
        return f"TVar({t.name})"
    elif isinstance(t, TFunc):
        return f"TFunc({type_to_string(t.arg_type)}, {type_to_string(t.result_type)})"

def main():
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))

    subst = unify(t1, t2)

    if subst:
        for var_name, var_type in subst:
            if var_name == "a":
                print("a = TBool")
            elif var_name == "b":
                print("b = TInt")

if __name__ == "__main__":
    main()
